def backup(path: Path, root: Path):
    if path.exists():
        bdir = root / "backups" / "corporate_information_center_phase7_8_base_header_pro"
        bdir.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, bdir / (path.name + ".bak"))


def apply(root: Path):
    base = root / "app" / "templates" / "corporate_information_center" / "base.html"
    css = root / "app" / "static" / "css" / "corporate_information_center_v3_0_phase7_8_base_header_pro.css"
    base.parent.mkdir(parents=True, exist_ok=True)
    css.parent.mkdir(parents=True, exist_ok=True)
    backup(base, root)
    backup(css, root)
    base.write_text(BASE_TEMPLATE, encoding="utf-8")
    css.write_text(CSS_TEXT, encoding="utf-8")
    print(f"{VERSION}_APPLY_OK")
    print("Güncellenen dosyalar:")
    print(" - app\\templates\\corporate_information_center\\base.html")
    print(" - app\\static\\css\\corporate_information_center_v3_0_phase7_8_base_header_pro.css")


def gate(root: Path):
    base = root / "app" / "templates" / "corporate_information_center" / "base.html"
    css = root / "app" / "static" / "css" / "corporate_information_center_v3_0_phase7_8_base_header_pro.css"
    errors = []
    if not base.exists():
        errors.append("base.html bulunamadı")
        text = ""
    else:
        text = base.read_text(encoding="utf-8", errors="ignore")
    if not css.exists():
        errors.append("phase7_8 css bulunamadı")
    if VERSION not in (css.read_text(encoding="utf-8", errors="ignore") if css.exists() else ""):
        errors.append("CSS içinde faz imzası eksik")
    for bad in ["Planla, denetle, test et", "100Gönderime hazır", "Başarı oranı%", "ReleaseHazır", "<link rel=\"stylesheet\" href=\"{{ url_for('static'", "</h1>\nPersonel ve yönetici"]:
        if bad in text:
            errors.append(f"base.html içinde eski/bozuk ifade kaldı: {bad}")
    if "{% block title %}Kurumsal Bilgilendirme Merkezi | BYS360{% endblock %}" not in text:
        errors.append("title bloğu temiz değil")
    if "corporate_information_center_v3_0_phase7_8_base_header_pro.css" not in text:
        errors.append("phase7_8 css linki base.html içinde yok")
    if "cicp-command-header" not in text or "Gönderim kontrol ve canlı geçiş merkezi" not in text:
        errors.append("yeni profesyonel üst başlık bulunamadı")
    if "cicp-metrics" not in text:
        errors.append("kısa durum kartları bulunamadı")
    if "{{ tabs(_active_tab) }}" not in text:
        errors.append("tab menü çağrısı eksik")
    if errors:
        print(f"{VERSION}_GATE_FAIL")
        for e in errors:
            print("HATA:", e)
        return 2
    print(f"{VERSION}_GATE_OK")
    print(f"{VERSION}_FINAL_OK")
    return 0


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("-ProjectRoot", default="C:/bys360/project")
    ap.add_argument("-Mode", default="all")
    args = ap.parse_args()
    root = Path(args.ProjectRoot)
    if args.Mode in ("all", "apply"):
        apply(root)
    if args.Mode in ("all", "check", "gate"):
        return gate(root)
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
